        Assert.AreEqual("ch_abc", _provider.LastChargeId);
        Assert.AreEqual(1, _provider.RefundCallCount);
    }

    [TestMethod]
    public async Task RefundAsync_ProviderReturnsFalse_ReturnsFailureResult()
    {
        _provider.NextRefundResult = new RefundResult("re_fail", false);

        var result = await _gateway.RefundAsync("ch_123");

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public async Task RefundAsync_InvalidChargeId_ThrowsArgumentException(string? chargeId)
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync(chargeId!));
    }

    [TestMethod]
    public async Task RefundAsync_ProviderThrows_ExceptionPropagates()
    {
        _provider.RefundException = new InvalidOperationException("Refund service offline");

        await Assert.ThrowsExactlyAsync<InvalidOperationException>(
            async () => await _gateway.RefundAsync("ch_123"));
    }

    // ───────────────────── ProcessWebhook ──────────────────────────

    [TestMethod]
    [DataRow("charge.succeeded", true, "Charge confirmed")]
    [DataRow("charge.failed", false, "Charge declined")]
    [DataRow("refund.completed", true, "Refund processed")]
    public void ProcessWebhook_KnownEventType_ReturnsExpectedResult(
        string eventType, bool handled, string message)
    {
        var result = _gateway.ProcessWebhook(eventType, "{}");

        Assert.AreEqual(handled, result.Handled);
        Assert.AreEqual(message, result.Message);
    }

    [TestMethod]
    public void ProcessWebhook_UnknownEventType_ReturnsUnhandled()
    {
        var result = _gateway.ProcessWebhook("payment.unknown", "{}");

        Assert.IsFalse(result.Handled);
        Assert.Contains("Unknown event", result.Message);
    }

    [TestMethod]
    [DataRow(null, "payload")]
    [DataRow("", "payload")]
    [DataRow("   ", "payload")]
    [DataRow("charge.succeeded", null)]
    [DataRow("charge.succeeded", "")]
    [DataRow("charge.succeeded", "   ")]
    public void ProcessWebhook_InvalidArguments_ThrowsArgumentException(
        string? eventType, string? payload)
    {
        Assert.ThrowsExactly<ArgumentException>(
            () => _gateway.ProcessWebhook(eventType!, payload!));
    }
}

